<script setup lang="ts">import { Head, Link, router } from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import { Button } from '@/components/ui/button';import type { MarketingCampaign } from '@/types/marketingCampaign';defineProps<{campaigns:MarketingCampaign[]}>();function remove(id:number){
