}
}</script><template><Head title="Marketing Campaigns"/><div class="space-y-6 p-6"><div class="flex items-start justify-between"><PageHeader title="Marketing Campaigns" description="Manage dedicated homepage images and videos without adding them to the marketplace."/><Link href="/admin/marketing-campaigns/create"><Button>Create Campaign</Button></Link></div><div class="grid gap-5 lg:grid-cols-2"><article v-for="c in campaigns" :key="c.id" class="overflow-hidden rounded-2xl border bg-background"><div class="aspect-video bg-muted"><video v-if="c.media_type==='video'" :src="c.media_url??undefined" :poster="c.poster_url??undefined" class="h-full w-full object-cover" muted/><img v-else :src="c.media_url??''" :alt="c.name" class="h-full w-full object-cover"/></div><div class="p-5"><div class="flex items-start justify-between gap-4"><div><h2 class="font-semibold">{{c.name}}</h2><p class="mt-1 text-sm text-muted-foreground">{{c.media_type}} · {{c.is_current?'Currently eligible':c.is_active?'Scheduled':'Inactive'}}</p></div><span :class="['rounded-full px-2 py-1 text-xs',c.is_current?'bg-emerald-100 text-emerald-700':'bg-muted']">{{c.is_current?'Live':'Not live'}}</span></div><div class="mt-5 flex justify-end gap-2"><Link :href="`/admin/marketing-campaigns/${c.id}/edit`"><Button size="sm" variant="outline">Edit</Button></Link><Button size="sm" variant="destructive" @click="remove(c.id)">Delete</Button></div></div></article><div v-if="!campaigns.length" class="rounded-2xl border border-dashed p-10 text-center text-muted-foreground">No campaigns yet.</div></div></div></template>